import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

max_reduce_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

// A kernel to reduce a 3D tensor x (shape [N, D, M]) to an output tensor out
// along a given dimension (0, 1, or 2). We assume x is float32.
__global__ void max_reduce_kernel_3d(
    const float* __restrict__ x,
    float* __restrict__ out,
    const int N,
    const int D,
    const int M,
    const int dim
) {
    // Each thread will compute 1 output element.
    // Indexing depends on which dim we are reducing.
    int out_size = 1;
    if (dim == 0) {            // reduce over N
        out_size = D * M;
    } else if (dim == 1) {     // reduce over D
        out_size = N * M;
    } else {                   // reduce over M
        out_size = N * D;
    }

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= out_size) return;

    if (dim == 0) {
        // out shape = [D, M], idx -> (d, m)
        int d = idx / M; 
        int m = idx % M;
        float mx = -FLT_MAX;
        for (int n = 0; n < N; n++) {
            float val = x[n * D * M + d * M + m];
            if (val > mx) {
                mx = val;
            }
        }
        out[d * M + m] = mx;
    } else if (dim == 1) {
        // out shape = [N, M], idx -> (n, m)
        int n = idx / M;
        int m = idx % M;
        float mx = -FLT_MAX;
        for (int d = 0; d < D; d++) {
            float val = x[n * D * M + d * M + m];
            if (val > mx) {
                mx = val;
            }
        }
        out[n * M + m] = mx;
    } else {
        // out shape = [N, D], idx -> (n, d)
        int n = idx / D;
        int d = idx % D;
        float mx = -FLT_MAX;
        for (int m = 0; m < M; m++) {
            float val = x[n * D * M + d * M + m];
            if (val > mx) {
                mx = val;
            }
        }
        out[n * D + d] = mx;
    }
}

// A wrapper that takes the input tensor x, dimension dim, and launches our kernel.
// We assume x is 3D (batch_size, dim1, dim2). 
torch::Tensor max_reduce_cuda(torch::Tensor x, int64_t dim) {
    // We only handle float32 and 3D for demonstration.
    TORCH_CHECK(x.dim() == 3, "Input must be 3D");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "Only float32 supported");

    int64_t N = x.size(0);
    int64_t D = x.size(1);
    int64_t M = x.size(2);
    TORCH_CHECK(dim >= 0 && dim < 3, "dim must be in [0,2]");

    // Decide the output shape
    std::vector<int64_t> out_shape;
    if (dim == 0) {
        out_shape = {D, M};
    } else if (dim == 1) {
        out_shape = {N, M};
    } else { // dim == 2
        out_shape = {N, D};
    }

    auto out = torch::empty(out_shape, x.options());
    auto x_ptr = x.data_ptr<float>();
    auto out_ptr = out.data_ptr<float>();

    int threads = 256;
    int out_size = 1;
    if (dim == 0) {
        out_size = D * M;
    } else if (dim == 1) {
        out_size = N * M;
    } else {
        out_size = N * D;
    }
    int blocks = (out_size + threads - 1) / threads;

    max_reduce_kernel_3d<<<blocks, threads>>>(x_ptr, out_ptr, N, D, M, dim);
    return out;
}
"""

max_reduce_cpp_source = r"""
torch::Tensor max_reduce_cuda(torch::Tensor x, int64_t dim);
"""

# Build the inline extension
max_reduce_ext = load_inline(
    name="max_reduce_ext",
    cpp_sources=max_reduce_cpp_source,
    cuda_sources=max_reduce_source,
    extra_cflags=["-std=c++17"],
    extra_ldflags=[],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Simple model that performs Max reduction over a specific dimension using a custom CUDA kernel.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Use our custom CUDA-based max reduction
        return max_reduce_ext.max_reduce_cuda(x, self.dim)
